public class Main {
    static void reverse(int[] a, int from, int to) {
        while (from < to) {
            int temp = a[from];
            a[from] = a[to];
            a[to] = temp;
            from++;
            to--;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(sc.next());
        }
        int k = Integer.parseInt(sc.next()) % n;
        reverse(a, 0, n - 1);
        reverse(a, 0, k - 1);
        reverse(a, k, n - 1);
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) {
                out.append(" ");
            }
            out.append(a[i]);
        }
        System.out.println(out);
    }
